function validate([ranges]) {
  if (!Array.isArray(ranges) || ranges.length < 1 || ranges.length > 100000) return 'ranges needs 1 to 10^5 entries.';
  for (const r of ranges) {
    if (!Array.isArray(r) || r.length !== 2) return 'Each range is a pair [start, end].';
    const [start, end] = r;
    if (!Number.isInteger(start) || !Number.isInteger(end)) return 'Range endpoints are integers.';
    if (start < 0 || end > 1000000000) return 'Endpoints are between 0 and 10^9.';
    if (start > end) return 'Each range needs start <= end.';
  }
  return null;
}

